new file mode 100644
index 0000000..6a1bd8f
--- /dev/null
+++ b/src/domain/sites.js
@@ -0,0 +1,18 @@
+// Kitchen sites and the storage locations belonging to each one.
+import { AppError } from "../errors.js";
+
+export const DEFAULT_SITE = "main";
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** Set of location ids belonging to `site` (string id or `{ site }`). */
+export function siteLocations(store, site = DEFAULT_SITE) {
+  const id = typeof site === "object" && site !== null ? (site.site ?? DEFAULT_SITE) : site;
+  getSite(store, id);
+  return new Set(store.data.locations.filter((l) => l.site === id).map((l) => l.id));
+}
